// ============================================================
// 猪来了NextBot - 枪战模式（打猪枪战 pigshoot / PVP枪战 pvpgun）
// 第一人称射击：MK14 / USAS12 双武器、换弹、切枪、全自动/半自动、波次猪群
// 音频：循环源（gunSrc/gunGain/usas12Src/usas12Gain），不逐发射击层
// ============================================================

const GUN_WEAPONS = [
  { name: 'MK14',   rpm: 700, damage: 15, mag: 30, reload: 1.6, spread: 0.018, pellets: 1, recoil: 1.0, bloom: 0.15, range: 70, auto: true  },
  { name: 'USAS12', rpm: 235, damage: 14, mag: 20, reload: 2.5, spread: 0.07,  pellets: 8, recoil: 1.8, bloom: 0.35, range: 32, auto: true  },
];
const GUN_CFG = {
  FIELD: 60,
  PIG_BASE_HP: 40, PIG_HP_PER_WAVE: 5,
  PIG_BASE_SPEED: 3.3, PIG_SPEED_PER_WAVE: 0.22, PIG_MAX_SPEED: 9.5,
  PIG_CONTACT_DMG: 15, HURT_CD: 0.8,
  WAVE_BASE_PIGS: 2,
  WAVE_DELAY: 4,
  MAX_PIGS_ALIVE: 12,
};

// ===== 枪战全局状态 =====
let gun = {
  active: false,
  mode: '',              // 'pigshoot' | 'pvpgun'
  weapon: 0,
  ammo: [GUN_WEAPONS[0].mag, GUN_WEAPONS[1].mag],
  reloading: 0,
  fireMode: 0,           // 0=全自动 1=半自动
  firing: false,
  fireTimer: 0,
  recoil: 0,
  bloom: 1.0,
  kills: 0,
  // 波次（仅 pigshoot）
  wave: 0,
  waveActive: false,
  waveDelay: 0,
  pigs: [],
  endless: false,
  endlessLevel: 1,
  endlessSpawnDelay: 0,
  // 受击
  hurtCd: 0,
  // 视图
  gunGroup: null,
  gunMeshA: null, gunMeshB: null,
  muzzle: null,
  muzzleT: 0,
};

// ===== 循环音频源 =====
let gunActx = null, gunMasterGain = null;
let gunBuf = null;
let gunSrc = null, gunGain = null;
let usas12Src = null, usas12Gain = null, usas12Filter = null;
let gunAudioReady = false;

function gunEnsureAudio() {
  try {
    if (!gunActx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      gunActx = new AC();
      gunMasterGain = gunActx.createGain();
      gunMasterGain.gain.value = 0.9;
      gunMasterGain.connect(gunActx.destination);
    }
    if (gunActx.state === 'suspended') gunActx.resume();
    if (gunAudioReady) return;
    // 解码内嵌枪声
    const b64 = '';
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    gunActx.decodeAudioData(bytes.buffer).then(function (buf) {
      gunBuf = buf;
      // MK14 循环源
      gunSrc = gunActx.createBufferSource();
      gunSrc.buffer = buf; gunSrc.loop = true;
      gunGain = gunActx.createGain(); gunGain.gain.value = 0;
      gunSrc.connect(gunGain); gunGain.connect(gunMasterGain);
      gunSrc.start();
      // USAS12 循环源（同一素材，低通+增益区分音色）
      usas12Src = gunActx.createBufferSource();
      usas12Src.buffer = buf; usas12Src.loop = true;
      usas12Filter = gunActx.createBiquadFilter();
      usas12Filter.type = 'lowpass'; usas12Filter.frequency.value = 900;
      usas12Gain = gunActx.createGain(); usas12Gain.gain.value = 0;
      usas12Src.connect(usas12Filter); usas12Filter.connect(usas12Gain); usas12Gain.connect(gunMasterGain);
      usas12Src.start();
      gunAudioReady = true;
    }).catch(function (e) { console.warn('gun audio decode failed', e); });
  } catch (e) { console.warn('gun audio init failed', e); }
}
// 开火时提升对应武器循环源音量，停火时归零（不逐发射击层）
function gunUpdateAudioGates() {
  if (!gunAudioReady || !gunActx) return;
  const t = gunActx.currentTime;
  const firing = gun.firing && gun.fireTimer <= 0 && gun.reloading <= 0 && gun.ammo[gun.weapon] > 0;
  const mkTarget = (firing && gun.weapon === 0) ? 0.9 : 0;
  const usTarget = (firing && gun.weapon === 1) ? 0.95 : 0;
  gunGain.gain.setTargetAtTime(mkTarget, t, 0.03);
  usas12Gain.gain.setTargetAtTime(usTarget, t, 0.03);
}

// ===== 武器视图模型（简单几何枪，挂到相机）=====
function gunCreateViewmodel() {
  gunCleanupViewmodel();
  gun.gunGroup = new THREE.Group();
  const dark = new THREE.MeshBasicMaterial({ color: 0x1a1a1f, transparent: true });
  const metal = new THREE.MeshBasicMaterial({ color: 0x33333c, transparent: true });
  // MK14：长枪管+机匣
  const body = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.14, 0.62), dark);
  body.position.set(0, 0, 0);
  const barrel = new THREE.Mesh(new THREE.BoxGeometry(0.045, 0.045, 0.5), metal);
  barrel.position.set(0, 0.03, -0.5);
  const grip = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.2, 0.12), dark);
  grip.position.set(0, -0.13, 0.12);
  const sight = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.06, 0.08), metal);
  sight.position.set(0, 0.11, -0.1);
  gun.gunMeshA = new THREE.Group();
  gun.gunMeshA.add(body); gun.gunMeshA.add(barrel); gun.gunMeshA.add(grip); gun.gunMeshA.add(sight);
  // USAS12：更粗短
  const body2 = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.16, 0.5), dark);
  const barrel2 = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.07, 0.4), metal);
  barrel2.position.set(0, 0.02, -0.4);
  const drum = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.16, 0.14), metal);
  drum.position.set(0, -0.05, 0.05);
  gun.gunMeshB = new THREE.Group();
  gun.gunMeshB.add(body2); gun.gunMeshB.add(barrel2); gun.gunMeshB.add(drum);
  gun.gunGroup.add(gun.gunMeshA);
  gun.gunGroup.add(gun.gunMeshB);
  gun.gunGroup.position.set(0.28, -0.22, -0.55);
  gun.gunGroup.renderOrder = 999;
  camera.add(gun.gunGroup);
  gunUpdateViewmodel();
}
function gunCleanupViewmodel() {
  if (gun.gunGroup && camera) { camera.remove(gun.gunGroup); }
  gun.gunGroup = null; gun.gunMeshA = null; gun.gunMeshB = null;
}
function gunUpdateViewmodel() {
  if (!gun.gunGroup) return;
  if (gun.gunMeshA) gun.gunMeshA.visible = (gun.weapon === 0);
  if (gun.gunMeshB) gun.gunMeshB.visible = (gun.weapon === 1);
}

// ===== 初始化 / 清理 =====
function gunInit(mode) {
  gun.active = true;
  gun.mode = mode;
  gun.weapon = 0;
  gun.ammo = [GUN_WEAPONS[0].mag, GUN_WEAPONS[1].mag];
  gun.reloading = 0; gun.fireMode = 0; gun.firing = false; gun.fireTimer = 0;
  gun.recoil = 0; gun.bloom = 1.0; gun.kills = 0;
  gun.wave = 0; gun.waveActive = false; gun.waveDelay = 2.5;
  gun.pigs = [];
  // 无尽模式由子菜单选择（_pigshootRule），单人/多人均可玩
  gun.endless = (mode === 'pigshoot' && window._pigshootRule === 'endless');
  gun.endlessLevel = 1; gun.endlessSpawnDelay = 0;
  gun.hurtCd = 0;
  gun.retargetTimer = 8;
  // 地图
  buildEmptyArena();
  hideMaze();
  // 隐藏剑
  if (swordGroup) swordGroup.visible = false;
  swordEquipped = false;
  // 隐藏 nextbot
  if (nextbot.mesh) nextbot.mesh.visible = false;
  if (nextbot.glowMesh) nextbot.glowMesh.visible = false;
  nextbot.alive = false;
  if (nextbotAudio && !nextbotAudio.paused) nextbotAudio.pause();
  // 武器视图
  gunCreateViewmodel();
  // 显示HUD
  gunShowHud(true);
  gunEnsureAudio();
  if (mode === 'pigshoot') {
    if (typeof showToast === 'function') showToast(gun.endless ? '打猪枪战 · 无尽模式' : '打猪枪战 · 波次模式', 1800);
  } else {
    if (typeof showToast === 'function') showToast('PVP枪战 · 消灭你的对手！', 1800);
  }
  gunUpdateHud();
}
function gunCleanup() {
  gun.active = false;
  // 移除猪
  for (const p of gun.pigs) {
    if (p.mesh) scene.remove(p.mesh);
    if (p.glowMesh) scene.remove(p.glowMesh);
  }
  gun.pigs = [];
  gunCleanupViewmodel();
  gunShowHud(false);
  // 关闭枪声循环源
  if (gunGain) gunGain.gain.setTargetAtTime(0, gunActx.currentTime, 0.02);
  if (usas12Gain) usas12Gain.gain.setTargetAtTime(0, gunActx.currentTime, 0.02);
  gun.firing = false;
}

// ===== HUD =====
function gunShowHud(show) {
  const ids = ['gunCrosshair', 'gunAmmo', 'gunWaveInfo', 'gunFireBtn', 'gunReloadBtn', 'gunSwitchBtn'];
  for (const id of ids) {
    const el = document.getElementById(id);
    if (el) el.style.display = show ? 'block' : 'none';
  }
  // 枪战模式隐藏原剑攻击键/物品栏
  const atk = document.getElementById('attackBtn');
  if (atk) atk.style.display = show ? 'none' : atk.style.display;
  const hb = document.getElementById('hotbar');
  if (hb) hb.style.display = show ? 'none' : hb.style.display;
  const hc = document.getElementById('healthBarContainer');
  if (hc) hc.style.display = show ? 'block' : hc.style.display;
}
function gunUpdateHud() {
  const w = GUN_WEAPONS[gun.weapon];
  const ammoEl = document.getElementById('gunAmmo');
  if (ammoEl) {
    let txt = w.name + ' ' + gun.ammo[gun.weapon] + '/' + w.mag;
    txt += gun.reloading > 0 ? '  [换弹中]' : '';
    txt += gun.fireMode === 0 ? ' [全自动]' : ' [半自动]';
    ammoEl.textContent = txt;
  }
  const waveEl = document.getElementById('gunWaveInfo');
  if (waveEl) {
    if (gun.mode === 'pvpgun') {
      waveEl.textContent = '击杀: ' + (window.pvpKills || 0) + (gun.kills ? '  本局击杀:' + gun.kills : '');
    } else if (gun.endless) {
      waveEl.textContent = '无尽 · 击杀 ' + gun.kills + ' · 等级 ' + gun.endlessLevel;
    } else {
      waveEl.textContent = gun.waveActive ? ('第 ' + gun.wave + ' 波 · 剩余 ' + gun.pigs.filter(p => p.alive).length)
        : (gun.wave > 0 ? ('第 ' + (gun.wave + 1) + ' 波 ' + Math.ceil(gun.waveDelay) + 's') : '准备…');
    }
  }
}

// ===== 射击 =====
function gunHorizForward() {
  return { x: -Math.sin(player.yaw), z: -Math.cos(player.yaw) };
}
function gunFullForward() {
  const cp = Math.cos(player.pitch), sp = Math.sin(player.pitch);
  return { x: -Math.sin(player.yaw) * cp, y: sp * Math.cos(player.yaw), z: -Math.cos(player.yaw) * cp };
}
function gunCanFire() {
  return gun.active && gameRunning && !gamePaused && gun.reloading <= 0 &&
    !(MP.mode === 'client' && MP._clientDead) && !(MP.mode === 'host' && MP._hostDead) && playerHealth > 0;
}
function gunStartFire() {
  if (!gunCanFire()) return;
  gun.firing = true;
  if (gun.fireMode === 1) { gunTryShoot(); } // 半自动：点一下射一发
}
function gunStopFire() { gun.firing = false; }
function gunTryShoot() {
  if (!gunCanFire()) return;
  if (gun.fireTimer > 0) return;
  if (gun.ammo[gun.weapon] <= 0) { gunTryReload(); return; }
  const w = GUN_WEAPONS[gun.weapon];
  gun.fireTimer = 60 / w.rpm;
  gun.ammo[gun.weapon]--;
  gun.recoil += w.recoil;
  gun.bloom = Math.min(2.5, gun.bloom + w.bloom);
  let effDmg = w.damage;
  if (typeof devCheat !== 'undefined' && devCheat.active && devCheat.damage > 0) effDmg = devCheat.damage;
  gunSpawnPellets(w, effDmg);
  gunMuzzleFlash();
  gunUpdateHud();
}
function gunSpawnPellets(w, damageOverride) {
  for (let i = 0; i < w.pellets; i++) {
    // 散布：水平/垂直方向加随机角偏移
    const ang = (Math.random() - 0.5) * 2 * w.spread * gun.bloom;
    const pitchOff = (Math.random() - 0.5) * 2 * w.spread * gun.bloom;
    const cy = Math.cos(player.yaw), sy = Math.sin(player.yaw);
    // 水平方向 + 散布
    let fx = -sy, fz = -cy;
    const cosA = Math.cos(ang), sinA = Math.sin(ang);
    const rx = fx * cosA - fz * sinA;
    const rz = fx * sinA + fz * cosA;
    const pitch = player.pitch + pitchOff;
    const cp = Math.cos(pitch), sp = Math.sin(pitch);
    const dirX = rx * cp, dirY = sp * cy, dirZ = rz * cp;
    gunCastRay(dirX, dirY, dirZ, (damageOverride !== undefined ? damageOverride : w.damage), w.range);
  }
}
// 简易射线命中：目标为猪（pigshoot）或玩家（pvpgun）
function gunCastRay(dirX, dirY, dirZ, damage, range) {
  if (typeof devAutoAim === 'function' && devAutoAim()) {
    const ta = gunAutoAimTarget();
    if (ta) { gunHitTarget(ta, damage); return; }
  }
  const ox = player.x, oz = player.z;
  const eyeY = PLAYER_H + player.jumpY;
  let bestT = range, hitPig = null, hitPlayer = null;
  const pigR = 1.1;
  // 猪目标
  for (const p of gun.pigs) {
    if (!p.alive) continue;
    const tx = p.x - ox, ty = (NEXTBOT_SIZE / 2) - eyeY, tz = p.z - oz;
    // 投影到射线
    const proj = tx * dirX + ty * dirY + tz * dirZ;
    if (proj < 0 || proj > bestT) continue;
    // 垂足到猪中心距离
    const px = ox + dirX * proj, py = eyeY + dirY * proj, pz = oz + dirZ * proj;
    const dx = px - p.x, dz = pz - p.z;
    const horiz = Math.sqrt(dx * dx + dz * dz);
    if (horiz < pigR && py > 0 && py < NEXTBOT_SIZE + 0.5) { bestT = proj; hitPig = p; }
  }
  // 玩家目标（pvpgun）
  if (gun.mode === 'pvpgun') {
    const players = gunCollectRemotePlayers();
    for (const rp of players) {
      if (rp.dead) continue;
      if (rp.isLocal) continue;
      const tx = rp.x - ox, ty = 1.2 - eyeY, tz = rp.z - oz;
      const proj = tx * dirX + ty * dirY + tz * dirZ;
      if (proj < 0 || proj > bestT) continue;
      const px = ox + dirX * proj, py = eyeY + dirY * proj, pz = oz + dirZ * proj;
      const dx = px - rp.x, dz = pz - rp.z;
      const horiz = Math.sqrt(dx * dx + dz * dz);
      if (horiz < 0.9 && py > 0.2 && py < 2.6) { bestT = proj; hitPlayer = rp; }
    }
  }
  if (hitPig) {
    gunDamagePig(hitPig, damage);
  } else if (hitPlayer) {
    gunDamagePlayer(hitPlayer, damage);
  }
}
function gunCollectRemotePlayers() {
  const list = [];
  if (MP.mode === 'host') {
    for (const id in MP.players) { const p = MP.players[id]; if (p) list.push(p); }
  } else if (MP.mode === 'client') {
    for (const id in MP.remotePlayers) { const rp = MP.remotePlayers[id]; if (rp) list.push(rp); }
  }
  return list;
}
function gunDamagePig(p, dmg) {
  // 客户端：上报主机权威扣血
  if (MP.mode === 'client') {
    if (typeof Bridge !== 'undefined' && MP._handshakeToken) {
      Bridge.send(JSON.stringify({ type:'gunHitPig', token: MP._handshakeToken, px:p.x, pz:p.z, damage:dmg }));
    }
    return;
  }
  p.health -= dmg;
  if (p.hpSprite) drawSurvivalPigHP(p.hpSprite, p.health);
  if (typeof spawnHitParticles === 'function') spawnHitParticles(p.x, 1.4, p.z);
  if (p.health <= 0 && p.alive) {
    p.alive = false;
    gun.kills++;
    window.pvpKills = (window.pvpKills || 0) + 1;
    recordKill('pigshoot');
    if (typeof spawnKillBurst === 'function') spawnKillBurst(p.x, 1.4, p.z);
    if (p.mesh) p.mesh.visible = false;
    if (p.glowMesh) p.glowMesh.visible = false;
    p.respawnTimer = 1.5;
    if (!gun.endless) {
      // 波次模式：本只计入剩余
      if (!p.counted) { p.counted = true; }
      if (gun.pigs.every(q => !q.alive || q.counted)) {
        // 波次清空
        if (gun.pigs.filter(q => q.counted).length >= gun.waveTotal) {
          gun.waveActive = false;
          gun.waveDelay = GUN_CFG.WAVE_DELAY;
          if (typeof showToast === 'function') showToast('第 ' + gun.wave + ' 波清空！', 1500);
        }
      }
    } else {
      // 无尽：节奏补猪
      gun.endlessLevel = 1 + Math.floor(gun.kills / 10);
    }
  }
  const flash = document.getElementById('hitFlash');
  if (flash) { flash.style.opacity = '1'; setTimeout(() => flash.style.opacity = '0', 60); }
}
function gunDamagePlayer(rp, dmg) {
  // 联机：主机权威扣血；客户端本地仅视觉
  if (MP.mode === 'client') {
    // 通知主机命中（LAN信任模式）
    if (typeof Bridge !== 'undefined' && MP._handshakeToken) {
      Bridge.send(JSON.stringify({ type: 'gunHit', token: MP._handshakeToken, victim: rp.id, damage: dmg }));
    }
    if (typeof spawnHitParticles === 'function') spawnHitParticles(rp.x, 1.2, rp.z, 0x66aaff);
    return;
  }
  rp.health -= dmg;
  rp.invincible = 0.3;
  if (typeof spawnHitParticles === 'function') spawnHitParticles(rp.x, 1.2, rp.z, 0x66aaff);
  if (rp.health <= 0) {
    rp.health = 0; rp.dead = true; rp.alive = false;
    rp.respawnTimer = MP.RESPAWN_TIME;
    if (typeof spawnKillBurst === 'function') spawnKillBurst(rp.x, 1.4, rp.z);
    if (rp.mesh) setPlayerDead(rp.mesh, true);
    window.pvpKills = (window.pvpKills || 0) + 1;
    recordKill('pvpgun');
    if (MP.mode === 'host' && typeof Bridge !== 'undefined') {
      Bridge.broadcast(JSON.stringify({ type: 'pvpKill', killer: 'host', victim: rp.id, killerName: MP.myName, victimName: rp.name }));
    }
  }
}

// ===== 换弹 / 切枪 / 射速档 =====
function gunTryReload() {
  if (!gun.active || gun.reloading > 0) return;
  const w = GUN_WEAPONS[gun.weapon];
  if (gun.ammo[gun.weapon] >= w.mag) return;
  gun.reloading = w.reload;
  gun.firing = false;
  gunUpdateHud();
}
function gunSwitchWeapon(i) {
  if (!gun.active || gun.reloading > 0) return;
  if (i === gun.weapon) return;
  gun.weapon = i;
  gun.firing = false;
  gun.bloom = 1.0;
  gunUpdateViewmodel();
  gunUpdateHud();
}
function gunToggleFireMode() {
  if (!gun.active) return;
  gun.fireMode = gun.fireMode === 0 ? 1 : 0;
  if (typeof showToast === 'function') showToast(GUN_WEAPONS[gun.weapon].name + ' → ' + (gun.fireMode === 0 ? '全自动' : '半自动'), 1000);
  gunUpdateHud();
}

// ===== 枪口火光 =====
function gunMuzzleFlash() {
  gun.muzzleT = 0.05;
}

// ===== 波次猪生成 =====
function gunSpawnPig() {
  const visual = createSurvivalPigVisual();
  const mesh = visual.mesh, glowMesh = visual.glowMesh, hpSprite = visual.hpSprite;
  const half = GUN_CFG.FIELD / 2 - 4;
  const side = Math.floor(Math.random() * 4);
  let x, z;
  if (side === 0) { x = (Math.random() - 0.5) * half * 2; z = -half; }
  else if (side === 1) { x = (Math.random() - 0.5) * half * 2; z = half; }
  else if (side === 2) { x = -half; z = (Math.random() - 0.5) * half * 2; }
  else { x = half; z = (Math.random() - 0.5) * half * 2; }
  mesh.position.set(x, NEXTBOT_SIZE / 2 + 0.15, z);
  glowMesh.position.copy(mesh.position);
  scene.add(mesh); scene.add(glowMesh);
  const hp = GUN_CFG.PIG_BASE_HP + (gun.wave - 1) * GUN_CFG.PIG_HP_PER_WAVE;
  const spd = Math.min(GUN_CFG.PIG_BASE_SPEED + (gun.wave - 1) * GUN_CFG.PIG_SPEED_PER_WAVE, GUN_CFG.PIG_MAX_SPEED);
  return { x, z, mesh, glowMesh, hpSprite, health: hp, maxHp: hp, alive: true, respawnTimer: 0, counted: false, speed: spd,
    stuckTimer: 0, lastX: x, lastZ: z, wanderT: 0, wanderAngle: 0, targetId: null };
}
function gunStartWave() {
  gun.wave++;
  gun.waveActive = true;
  const count = GUN_CFG.WAVE_BASE_PIGS + Math.floor(gun.wave * 1.5);
  gun.waveTotal = count;
  for (let i = 0; i < count; i++) gun.pigs.push(gunSpawnPig());
  gunAssignPigTargets();
  if (typeof showToast === 'function') showToast('第 ' + gun.wave + ' 波！' + count + '只猪来袭！', 1800);
  gunUpdateHud();
}

// ===== 主更新 =====
function gunUpdate(dt) {
  if (!gun.active || !gameRunning) return;
  // 计时
  if (gun.reloading > 0) {
    gun.reloading -= dt;
    if (gun.reloading <= 0) { gun.ammo[gun.weapon] = GUN_WEAPONS[gun.weapon].mag; gun.reloading = 0; }
    gunUpdateHud();
  }
  if (gun.fireTimer > 0) gun.fireTimer -= dt;
  if (gun.hurtCd > 0) gun.hurtCd -= dt;
  // 持续开火（全自动）
  if (gun.firing && gun.fireMode === 0) gunTryShoot();
  // 后坐力恢复 + bloom 衰减
  gun.recoil = Math.max(0, gun.recoil - dt * 6);
  gun.bloom = Math.max(1.0, gun.bloom - dt * 3);
  // 枪口火光衰减
  if (gun.muzzleT > 0) gun.muzzleT -= dt;
  if (MP.mode === 'host' && typeof gunCheckRespawnRefill === 'function') gunCheckRespawnRefill(dt);
  // 音频门控
  gunUpdateAudioGates();
  // 猪AI（仅 pigshoot，主机/单机权威）
  if (gun.mode === 'pigshoot' && (MP.mode === 'offline' || MP.mode === 'host')) {
    gun.retargetTimer -= dt;
    if (gun.retargetTimer <= 0) { gun.retargetTimer = 8; gunAssignPigTargets(); }
    gunUpdatePigs(dt);
  }
  gunUpdateHud();
}
function gunUpdatePigs(dt) {
  // 波次推进
  if (!gun.waveActive && !gun.endless) {
    if (gun.waveDelay > 0) {
      gun.waveDelay -= dt;
      if (gun.waveDelay <= 0) gunStartWave();
    }
  }
  // 无尽模式补猪
  if (gun.endless) {
    const aliveCount = gun.pigs.filter(p => p.alive).length;
    const maxAlive = Math.min(3 + gun.endlessLevel, GUN_CFG.MAX_PIGS_ALIVE);
    gun.endlessSpawnDelay -= dt;
    if (aliveCount < maxAlive && gun.endlessSpawnDelay <= 0) {
      gun.pigs.push(gunSpawnPig());
      gun.endlessSpawnDelay = 1.2;
    }
  }
  const half = GUN_CFG.FIELD / 2 - 2;
  for (const p of gun.pigs) {
    if (!p.alive) {
      p.respawnTimer -= dt;
      if (p.respawnTimer <= 0 && gun.endless) {
        // 无尽模式原地复活
        p.alive = true; p.health = p.maxHp;
        const s = gunSpawnPigPos(); p.x = s.x; p.z = s.z;
        p.counted = false;
        if (p.mesh) { p.mesh.visible = true; p.mesh.position.set(p.x, NEXTBOT_SIZE / 2 + 0.15, p.z); }
        if (p.glowMesh) p.glowMesh.visible = true;
        drawSurvivalPigHP(p.hpSprite, p.health);
      }
      continue;
    }
    // 目标 = 该猪分配的 targetId（联机时每猪随机一个玩家，避免扎堆追一人）
    let tgtX = player.x, tgtZ = player.z;
    if (p.targetId && MP.mode === 'host') {
      const rp = MP.players[p.targetId];
      if (rp && !rp.dead) { tgtX = rp.x; tgtZ = rp.z; }
      else { const s = gunNearestSurvivor(p.x, p.z); if (s) { tgtX = s.x; tgtZ = s.z; } }
    }
    let dx = tgtX - p.x, dz = tgtZ - p.z;
    let dist = Math.sqrt(dx * dx + dz * dz);
    // 力场避障：与其他猪保持距离
    let pushX = 0, pushZ = 0;
    for (const q of gun.pigs) {
      if (q === p || !q.alive) continue;
      const qx = p.x - q.x, qz = p.z - q.z;
      const qd = Math.sqrt(qx * qx + qz * qz);
      if (qd > 0.01 && qd < 1.6) { pushX += (qx / qd) * (1.6 - qd); pushZ += (qz / qd) * (1.6 - qd); }
    }
    // 移动
    let mvx = 0, mvz = 0;
    if (dist > 0.1) { mvx = (dx / dist) * p.speed * dt; mvz = (dz / dist) * p.speed * dt; }
    mvx += pushX * dt * 3; mvz += pushZ * dt * 3;
    p.x += mvx; p.z += mvz;
    p.x = Math.max(-half, Math.min(half, p.x));
    p.z = Math.max(-half, Math.min(half, p.z));
    // 卡住检测突围
    p.stuckTimer += dt;
    if (p.stuckTimer > 1.2) {
      const moved = Math.abs(p.x - p.lastX) + Math.abs(p.z - p.lastZ);
      if (moved < 0.4) {
        // 卡住：随机方向突围
        p.wanderT = 0.6; p.wanderAngle = Math.random() * Math.PI * 2;
      }
      p.lastX = p.x; p.lastZ = p.z; p.stuckTimer = 0;
    }
    if (p.wanderT > 0) {
      p.wanderT -= dt;
      p.x += Math.cos(p.wanderAngle) * p.speed * dt;
      p.z += Math.sin(p.wanderAngle) * p.speed * dt;
    }
    // mesh
    if (p.mesh) {
      p.mesh.position.set(p.x, NEXTBOT_SIZE / 2 + 0.15, p.z);
      p.mesh.lookAt(camera.position.x, NEXTBOT_SIZE / 2 + 0.15, camera.position.z);
    }
    if (p.glowMesh) { p.glowMesh.position.copy(p.mesh.position); p.glowMesh.lookAt(camera.position.x, NEXTBOT_SIZE / 2 + 0.15, camera.position.z); }
    // 接触玩家扣血
    const hitR = NEXTBOT_SIZE * 0.55 + PLAYER_RADIUS;
    const pdx = p.x - player.x, pdz = p.z - player.z;
    if (Math.sqrt(pdx * pdx + pdz * pdz) < hitR && gun.hurtCd <= 0 && !devInvincible()) {
      playerHealth -= GUN_CFG.PIG_CONTACT_DMG;
      gun.hurtCd = GUN_CFG.HURT_CD;
      playerHitCooldown = GUN_CFG.HURT_CD;
      updateHealthUI();
      const fl = document.getElementById('hitFlash');
      if (fl) { fl.style.opacity = '1'; setTimeout(() => fl.style.opacity = '0', 120); }
      if (playerHealth <= 0) {
        playerHealth = 0;
        if (MP.mode === 'host') { MP._hostDead = true; MP._hostHealth = 0; MP._hostRespawnTimer = 2; if (typeof showHostDeath === 'function') showHostDeath(); }
        else if (MP.mode === 'offline') { gameOver('dead'); return; }
      }
    }
  }
}
function gunSpawnPigPos() {
  const half = GUN_CFG.FIELD / 2 - 4;
  const side = Math.floor(Math.random() * 4);
  if (side === 0) return { x: (Math.random() - 0.5) * half * 2, z: -half };
  if (side === 1) return { x: (Math.random() - 0.5) * half * 2, z: half };
  if (side === 2) return { x: -half, z: (Math.random() - 0.5) * half * 2 };
  return { x: half, z: (Math.random() - 0.5) * half * 2 };
}

// ===== 客户端Pig同步（联机时客户端看到主机的猪）=====
let _gunClientPigs = [];
function gunClientSyncPigs(arr) {
  // 由 multiplayer.js 调用：主机广播的猪列表
  if (!arr) return;
  // 清理旧mesh
  for (const p of _gunClientPigs) { if (p.mesh) scene.remove(p.mesh); if (p.glowMesh) scene.remove(p.glowMesh); }
  _gunClientPigs = [];
  for (const s of arr) {
    const visual = createSurvivalPigVisual();
    visual.mesh.position.set(s.x, NEXTBOT_SIZE / 2 + 0.15, s.z);
    visual.glowMesh.position.copy(visual.mesh.position);
    scene.add(visual.mesh); scene.add(visual.glowMesh);
    drawSurvivalPigHP(visual.hpSprite, s.health);
    _gunClientPigs.push({ mesh: visual.mesh, glowMesh: visual.glowMesh, x: s.x, z: s.z, hpSprite: visual.hpSprite });
  }
}
function gunClientClearPigs() {
  for (const p of _gunClientPigs) { if (p.mesh) scene.remove(p.mesh); if (p.glowMesh) scene.remove(p.glowMesh); }
  _gunClientPigs = [];
}

// ===== 猪目标分配（联机：每猪随机一个玩家，不扎堆）=====
function gunCollectAlivePlayers() {
  const list = [];
  if (MP.mode === 'offline') { list.push({ id:'self', x:player.x, z:player.z, dead:false }); return list; }
  if (!MP._hostDead) list.push({ id:'host', x:player.x, z:player.z, dead:false });
  for (const id in MP.players) { const rp = MP.players[id]; if (rp && !rp.dead) list.push({ id, x:rp.x, z:rp.z, dead:false }); }
  return list;
}
function gunAssignPigTargets() {
  if (gun.mode !== 'pigshoot') return;
  const players = gunCollectAlivePlayers();
  if (players.length === 0) return;
  for (const p of gun.pigs) {
    if (!p.alive) continue;
    // 目标死亡或未分配时随机重选
    const cur = p.targetId ? players.find(pl => pl.id === p.targetId) : null;
    if (!cur) {
      p.targetId = players[Math.floor(Math.random() * players.length)].id;
    }
  }
}
function gunNearestSurvivor(px, pz) {
  const players = gunCollectAlivePlayers();
  let best = null, bd = Infinity;
  for (const pl of players) { const d = (pl.x-px)**2 + (pl.z-pz)**2; if (d < bd) { bd = d; best = pl; } }
  return best;
}
// 复活后满弹（由 hostUpdateHostHealth 复活流程不直接调这里，故在 gunUpdate 检测复活事件）
let _prevHostDead = false;
function gunCheckRespawnRefill(dt) {
  const nowDead = (MP.mode === 'host' && MP._hostDead);
  if (_prevHostDead && !nowDead) {
    // 刚复活：满血满弹
    gun.ammo = [GUN_WEAPONS[0].mag, GUN_WEAPONS[1].mag];
    gun.reloading = 0; gun.hurtCd = 1.0;
    if (typeof showToast === 'function') showToast('复活！满血满弹', 1200);
  }
  _prevHostDead = nowDead;
}

// ===== 开发者自动锁敌 =====
// 找最近的可打击目标：pigshoot→最近活猪；pvpgun→最近活玩家
function gunAutoAimTarget() {
  const ox = player.x, oz = player.z;
  let best = null, bd = Infinity;
  if (gun.mode === 'pigshoot') {
    for (const p of gun.pigs) {
      if (!p.alive) continue;
      const d = (p.x-ox)**2 + (p.z-oz)**2;
      if (d < bd) { bd = d; best = { type:'pig', ref:p }; }
    }
  } else {
    for (const rp of gunCollectRemotePlayers()) {
      if (rp.dead || rp.isLocal) continue;
      const d = (rp.x-ox)**2 + (rp.z-oz)**2;
      if (d < bd) { bd = d; best = { type:'player', ref:rp }; }
    }
  }
  return best;
}
function gunHitTarget(ta, damage) {
  if (!ta) return;
  if (ta.type === 'pig') gunDamagePig(ta.ref, damage);
  else gunDamagePlayer(ta.ref, damage);
  if (typeof spawnHitParticles === 'function') {
    const r = ta.ref; spawnHitParticles(r.x, 1.3, r.z, ta.type === 'pig' ? 0xff4444 : 0x66aaff);
  }
}

// ===== 主机端：处理客户端命中 =====
function gunDamagePlayerHost(victim, dmg, clientId) {
  if (victim.dead) return;
  victim.health -= dmg;
  victim.invincible = 0.3;
  if (typeof spawnHitParticles === 'function') spawnHitParticles(victim.x, 1.2, victim.z, 0x66aaff);
  if (victim.health <= 0) {
    victim.health = 0; victim.dead = true; victim.alive = false;
    victim.respawnTimer = 2;
    if (typeof spawnKillBurst === 'function') spawnKillBurst(victim.x, 1.4, victim.z);
    if (victim.mesh) setPlayerDead(victim.mesh, true);
    recordKill('pvpgun');
    if (typeof Bridge !== 'undefined') {
      Bridge.broadcast(JSON.stringify({ type:'pvpKill', killer: MP.players[clientId] ? MP.players[clientId].name : '?', victim: victim.name }));
    }
  }
}
function gunApplyClientPigHit(px, pz, dmg) {
  // 主机：找最近的活猪（2.5m内）应用伤害
  let best = null, bd = 2.5*2.5;
  for (const p of gun.pigs) {
    if (!p.alive) continue;
    const d = (p.x-px)**2 + (p.z-pz)**2;
    if (d < bd) { bd = d; best = p; }
  }
  if (best) gunDamagePig(best, dmg);
}